// auth.jsx
import React, { createContext, useContext, useEffect, useState } from 'react';
import { jwtDecode } from "jwt-decode"; 


// Create AuthContext
const AuthContext = createContext();

// Function to get user information from the token
export const getUserFromToken = () => {
  const token = localStorage.getItem("token");
  if (!token) return null;

  try {
    const payload = jwtDecode(token); // Decode the token using jwt-decode
    return {
      userId: payload.id, // Adjust these keys based on your token's payload structure
      ownerId: payload.ownerId,
      clinicId: payload.clinicId,
    };
  } catch (error) {
    console.error("❌ Error decoding token:", error);
    return null;
  }
};

// AuthProvider component
export const AuthProvider = ({ children }) => {
  const [userInfo, setUserInfo] = useState({ userId: null, ownerId: null, clinicId: null });

  useEffect(() => {
    const user = getUserFromToken();
    if (user) {
      setUserInfo(user);
    }
  }, []);

  return (
    <AuthContext.Provider value={userInfo}>
      {children}
    </AuthContext.Provider>
  );
};

// Custom hook to use the AuthContext
export const useAuth = () => {
  return useContext(AuthContext);
};
